  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "San Francisco Just Cause Eviction Protections",
      "requirement": "Landlords may only evict tenants based on 16 enumerated just-cause grounds, which must be the dominant motive for recovery of possession. The landlord must provide written notice specifying the grounds and required statutory disclosures, and comply with warning/opportunity to cure and relocation payment rules where applicable.",
      "requirement_es": "Los propietarios solo pueden desalojar a los inquilinos por 16 motivos de causa justa enumerados, que deben ser el motivo dominante para recuperar la posesión. El propietario debe proporcionar una notificación por escrito que detalle las razones y las declaraciones obligatorias, y cumplir con los requisitos de advertencia, oportunidad de subsanar y pagos de reubicación cuando corresponda.",
      "key_value": {
        "label": "enumerated grounds for eviction",
        "value": "16 exclusive grounds"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "A landlord who resides in the same rental unit with their tenant may evict without just cause.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "A landlord who resides in the same rental unit with his or her tenant may evict said tenant without just cause"
              }
            ]
          }
        }
      ],
      "effective_date": "1980-08-24",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "supersedes",
        "target_scope": "local",
        "source_language": "Notwithstanding Section 37.3, this Section 37.9 shall apply as of August 24, 1980, to all landlords and tenants of rental units as defined in Section 37.2(r)."
      },
      "penalty": "Administrative penalties for failure to file statements of occupancy; defense to eviction; rebuttable presumption of retaliation for acts within six months.",
      "source_citation": "S.F. Admin. Code § 37.9",
      "quote": {
        "chunk": "c184",
        "start_words": "Notwithstanding Section 37.3, this Section 37.9",
        "end_words": "recover possession of a rental unit unless:"
      },
      "confidence": 0.98
    }
  ]
}
